from book import Chapter
c=Chapter('00')
c.src('ORIGINAL',2)
c.src('ORIGINAL',4,5,replacements=[('本文命名的的最主要原因','本文命名的最主要原因')])
c.add('''人的知识总是在一个个问题中生长。最初的问题也许很小：一件事为什么反复做不好，一个软件为什么总在重复相同的工作，一群明明都有知识和能力的人，为什么组织起来之后反而互相掣肘？顺着这些问题继续追问，我们会逐渐发现，许多看起来属于不同领域的困难，在更深处有着相似的结构。

一个人的知识，怎样变成其他人可以继续使用的知识？一个简单的构件，怎样组成具有新能力的复杂结构？一个能够长期存在的结构，又怎样保持改变自己的能力？这些问题既出现在数学和自然科学中，也出现在软件、人工智能以及人类社会的组织中。我要尝试的，就是把这些分散的问题连接起来，从中寻找更基本的共同规律。''')
c.heading('从数学与科学的关系开始')
c.src('ORIGINAL',6,9,replacements=[('更高级别的抽象水平上，更加正确的刻画','更高级别的抽象水平上，更准确地刻画'),('牛顿体系不过是宇宙在宏观低速层面上的近似物理规律','牛顿体系在弱引力、宏观低速等适用条件下，仍然是极其有效的近似理论'),('尝试以一种前所未有的方式，给出一个全新的数学抽象概念','尝试寻找更基本的数学抽象概念'),('是恰如其分的','表达了这项尝试所希望走的方向'),('“极限”的更泛化的数学抽象，是对旧原理的继承迭代和抽象升华','“极限”出发，寻找更泛化的数学抽象，尝试沿着这种研究方向继续前进')])
c.src('ORIGINAL',10,replacements=[('众所周知，牛顿的“哲学研究四原则”其实是奥卡姆剃刀原则的细化','牛顿的“哲学研究四原则”中，对原因、同类现象和经验归纳的考察，与奥卡姆剃刀所强调的简明性有相通之处'),('才是最为完美的终极方案','就是一个值得追求的方向')])
c.src('ORIGINAL',11,replacements=[('尽管当代关于科学体系的权威观点，将数学纳入形式科学范畴，比如维基百科关于科学分支的词条中有明确的文字描述。','数学也常被纳入形式科学的范围。'),('现代数学都是形式化公理系统，从不证自明的公理为起点','现代数学大量使用形式化公理系统，从明确选定的公理为起点'),('不断衍生出正确性得到充分保证的定理节点，逐步构建出一套具备一致性的理论系统','不断衍生出在这些前提下得到证明的定理节点，逐步构建理论系统'),('无懈-击','无懈可击')])
c.src('PREFACE-2024',9,replacements=[('如果连这一点都无法做到这一点的话','如果连这一点都无法做到的话'),('存粹','纯粹'),('无量量纲','无量纲'),('欧拉常数（e）','自然对数的底（e）'),('可以解释宇宙本质','能够刻画现实规律'),('如果说，这两者属于不同的范畴，是两类不同的事物，这样的想法显然是不合情理，说不通的','这使我很难满足于把两者截然分开、然后不再追问它们之间的关系')])
c.add('''例如，同样一个“3”，放在纸面上是一个数；写成三秒、三米、三千克，就分别对应了不同的测量过程。我们可以对数进行运算，却不能不加区别地把三米和三秒相加。数学关系要成为现实世界的规律，就需要说明对象是什么、怎样测量、哪些变化可以比较，以及在什么条件下，这个对应仍然成立。

反过来，一旦我们从具体对象中抽出了共同关系，同一套数学又能用到不同的地方。它不必为每一个苹果、每一块石头重新发明一种加法。这种把具体内容暂时放下、把结构保留下来的能力，正是知识可以跨越对象和领域不断积累的重要原因。''')
c.src('ORIGINAL',13,replacements=[('现代弦理论等最新的物理知识更是全面基于数学推理','弦理论等物理研究也大量借助数学构造'),('这个至今为止还没有人能够回答的问题','这个仍值得不断深入追问的问题')])
c.src('ORIGINAL',14,replacements=[('转变成于该体系中两个对象之间的正向和逆向对偶映射关系问题','转变成这个体系中，抽象结构与具体对象怎样互相对应的问题')])
c.src('PREFACE-2024',11,replacements=[('映射和逆映射缺一不可','既要看从具体对象到抽象结构的映射，也要看抽象结构能在什么条件下得到具体实现'),('通过逆向描述两者关系，更深刻的揭示两者的关系','通过反方向的考察，更深刻地理解两者的联系')])
c.heading('为什么要暂时走出熟悉的框架')
c.src('ORIGINAL',17,start='就像一个无知小儿',replacements=[('就像一个无知小儿','这就像一个初学者'),('这个时候，请务必再多给一点耐心继续读下去，因为顶尖的棋手','但顶尖的棋手'),('反直-觉','反直觉'),('这背后有着深刻的数学原理，一个复杂系统的演化，常常会陷入最优解的博弈状态之中','这个例子可以帮助我们理解，为什么一个复杂系统的演化，有时会陷入局部最优的状态之中'),('让你在陷入了局部最优解时','让自己在陷入局部最优解时'),('从而到达真正的全局最优','从而有机会走向更好的整体结果')])
c.add('''当然，弃子本身不等于高明，反对常识也不自动产生新知识。真正的区别，在于放弃一个前提之后，能不能解释原来解释不了的现象，能不能构造原来构造不出的东西，又能不能在实际使用中取得更好的结果。

我们也不需要因为一个理论可以继续发展，就否定它已经完成的工作。牛顿力学并没有因为相对论的出现而失去价值，日常工程仍然大量使用它。一个新框架如果有意义，应该能够说明旧框架为什么有效、在哪里有效，又为什么会在另一些条件下遇到困难。这样，重构才是在继承知识的基础上扩大能力。''')
c.src('ORIGINAL',25,26,replacements=[('任何理论都是建立在一套数学原理的基本规则之上的','如果希望把一个理论发展成可以精确推演和检验的体系，就需要找到适合它的基本规则和数学表达'),('最可能的是范畴论','值得认真考察的是范畴论')])
c.src('ORIGINAL',28,29,replacements=[('很显然，数学就是','从寻找共性的角度看，数学可以理解为'),('这些数学概念组成的数学结构中也都存在一些相同的结构，比如极限，余极限，万有性质等等','在适当的范畴中，还可以继续研究极限、余极限、万有性质等共同结构')])
c.src('ORIGINAL',30,replacements=[('所以范畴论作为最底层的理论基石，对于数学、科学理论以及宇宙万物都具备强大的第一性原理式的解释能力，对于很多看似极为复杂的问题，往往可以从底层的原理出发给出超级简单的答案','沿着这条线索，范畴论就可能为不同层级的知识提供一种共同的结构语言，使我们能够从更基本的关系出发重新考察复杂问题')])
c.src('ORIGINAL',31,33,replacements=[('真真面目','真面目'),('从最高处鸟瞰','从更高处鸟瞰')])
c.add('''鸟瞰能够看见道路之间的关系，却不能替代沿着道路实际走一遍。把两个事物放进同一种抽象语言，也不等于已经证明两者遵守同一个具体规律。这两个方向需要互相配合：向下追问，找出结构和条件；向上构造，考察这些构件在组合之后能产生什么能力。''')
c.heading('从理解世界到共同构造文明')
c.src('ORIGINAL',20,replacements=[('本文的最后一部分，主要聚焦于通过该统一理论框架对通用人工智能理论以及社会科学体系理论进行重构的一些设想','沿着这个方向继续研究，就会进入通用人工智能以及人类社会的组织问题')])
c.src('R54910',1,replacements=[('咱们之间的多个对话，横跨','这些问题横跨'),('其核心内容，其实都是出于我的那个基于第一性原理思考的原则','其核心内容，都是从第一性原理出发')])
c.src('R54910',8,replacements=[('而涌现出这些知识的神经网络，其组成结构和运行时的机制，社会层面和大脑层面，却有所不同','知识可以被许多个体共同使用，而产生和使用这些知识的组织，其结构和运行机制却有很大差别'),('生物层面的大脑中神经元与神经元之间的能力和地位是平等的，仅仅是所处的神经网络层的不同而已，其权重都是随时动态调整的','生物层面的大脑依靠大量不同神经元之间的连接和反馈形成能力，并没有一个单独的神经元以自己的身份永久支配一切'),('必然会导致','容易导致'),('(绝对的权力产生绝对的腐败，垄断阻碍创新等都是这个原因)','')])
c.src('R54910',10,replacements=[('而我现在正在做的这些事情，其实就是在准备好这个设想所需的不同拼图模块','要把这个设想落实下来，需要准备好不同的拼图模块'),('这个由AI大模型驱动的项目quick-launcher将','由 AI 驱动的个人工具可以'),('它将会成为','这样的工具可以成为')])
c.add('''如果知识仍然分散在互不相通的信息孤岛里，如果个人只能租用别人替自己保管的记忆，如果更强的智能仍然由少数组织控制，那么工具能力的提高，并不会自然带来人与人之间更加平等的关系。我们就需要同时考察知识如何保存、能力如何组合，以及生产和使用这些能力的组织如何运作。

因此，理论与实践并不是两件可以长期分开的事。我们可以先从一个人开始，把自己的资料、思考、代码和工具重新组织起来；再让几个人的知识和能力能够共同工作；然后逐步检验，这种组织方式能不能以更低的成本完成更复杂的任务，能不能让参与者获得更好的生活。抽象的问题，会在这些具体的构造中不断得到新的回答。''')
c.src('ORIGINAL',22,replacements=[('本文同样会涉及一部分演绎过程，即从这个新的原理概念出发尝试重构的过程，在这个过程中','在接下来的讨论中'),('以保证结论足够可靠，且符合绝大多数人的直觉','让读者能够判断每一步为什么成立，又在哪里需要继续考察')])
